fun {E} {F} [NormedAddCommGroup E] [NormedSpace ℝ E] [NormedAddCommGroup F] [NormedSpace ℝ F] [MeasurableSpace F]
    [BorelSpace F] [FiniteDimensional ℝ F] {g} γ x =>
  let f := fun t => ∫ (s : ℝ) in 0..t, γ.centering_density x s;
  let iso := StrictMono.orderIsoOfSurjective f ⋯ ⋯;
  (let __Equiv := iso.toEquiv;
    { toEquiv := __Equiv, map_zero' := ⋯, eqv' := ⋯ }).symm

